struct Date {
    int y;
    int m;
    int d;
};
int dayOfYear(struct Date dt) {
    int days[12] = {31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};
    int leap = (dt.y % 400 == 0) || (dt.y % 4 == 0 && dt.y % 100 != 0);
    int s = 0, i;
    if (leap)
        days[1] = 29;
    for (i = 0; i < dt.m - 1; i++)
        s += days[i];
    return s + dt.d;
}
int main(void) {
    struct Date dt;
    if (scanf("%d%d%d", &dt.y, &dt.m, &dt.d) != 3)
        return 0;
    printf("%d\n", dayOfYear(dt));
    return 0;
}

