    Node *head = NULL, *p, *tail = NULL;
    int n, i, x;
    if (scanf("%d", &n) != 1)
        return 0;
    for (i = 0; i < n; i++) {
        scanf("%d", &x);
        p = (Node *)malloc(sizeof(Node));
        if (p == NULL)
            return 1;
        p->data = x;
        p->next = NULL;
        if (head == NULL)
            head = p;
        else
            tail->next = p;
        tail = p;
    }
    for (p = head; p != NULL; p = p->next)
        printf("%d ", p->data);
    printf("\n");
    while (head != NULL) {
        Node *q = head;
        head = head->next;
        free(q);
    }
    return 0;
}

