struct Student {
    int num;
    int score;
};

struct Student *findBest(struct Student *p, int n) {
    struct Student *best = p;
    int i;

    for (i = 1; i < n; i++)
        if ((p + i)->score > best->score)
            best = p + i;
    return best;
}

int main(void) {
    struct Student st[50];
    struct Student *q;
    int n, i;

    if (scanf("%d", &n) != 1 || n < 1 || n > 50)
        return 1;
    for (i = 0; i < n; i++)
        if (scanf("%d %d", &st[i].num, &st[i].score) != 2)
            return 1;
    q = findBest(st, n);
    printf("%d %d\n", q->num, q->score);
    return 0;
}

