            return 1;
    for (i = 0; i < n - 1; i++)
        for (j = 0; j < n - 1 - i; j++)
            if (st[j].score < st[j + 1].score) {
                t = st[j];
                st[j] = st[j + 1];
                st[j + 1] = t;
            }
    for (i = 0; i < n; i++)
        printf("%d %d\n", st[i].num, st[i].score);
    return 0;
}

