#include <stdio.h>

struct Stat {
    int max;
    int min;
    int sum;
};

struct Stat calc(int a[], int n) {
    struct Stat r;
    int i;

    r.max = a[0];
    r.min = a[0];
    r.sum = 0;
    for (i = 0; i < n; i++) {
        if (a[i] > r.max)
            r.max = a[i];
        if (a[i] < r.min)
            r.min = a[i];
        r.sum = r.sum + a[i];
    }
    return r;
}

int main(void) {
    int a[100], n, i;
    struct Stat s;

    if (scanf("%d", &n) != 1 || n < 1 || n > 100)
        return 1;
    for (i = 0; i < n; i++)
        if (scanf("%d", &a[i]) != 1)
            return 1;
    s = calc(a, n);
    printf("%d %d %d\n", s.max, s.min, s.sum);
    return 0;
}

