struct Emp {
    char name[16];
    int salary;
};

int main(void) {
    struct Emp e[20], *p;
    char key[16];
    int n, i, found = -1;

    if (scanf("%d", &n) != 1 || n < 1 || n > 20)
        return 1;
    for (i = 0; i < n; i++)
        if (scanf("%s %d", e[i].name, &e[i].salary) != 2)
            return 1;
    if (scanf("%s", key) != 1)
        return 1;
    for (p = e; p < e + n; p++)
        if (strcmp(p->name, key) == 0) {
            found = (int)(p - e);
            break;
        }
    if (found < 0)
        printf("NOT FOUND\n");
    else
        printf("%d %d\n", found, e[found].salary);
    return 0;
}

