#include <stdio.h>
#include <stdlib.h>

struct node {
    char data;
    struct node *next;
};

/* 在值为 a 的结点前插入值为 key 的结点；若没有值为 a 的结点，则插在链表最后 */
void insert(struct node *head, char a, char key) {
    struct node *p = head;
    struct node *s;

    while (p->next != NULL && p->next->data != a)
        p = p->next;

    s = (struct node *)malloc(sizeof(struct node));
    if (s == NULL)
        return;
    s->data = key;
    s->next = p->next;
    p->next = s;
}

int main(void) {
    struct node *head, *tail, *p, *q;
    char ch, a, key;
    int first;

    head = (struct node *)malloc(sizeof(struct node));
    if (head == NULL)
        return 1;
    head->next = NULL;
    tail = head;

    /* 第一行：字符序列，以 $ 结束 */
    while (scanf("%c", &ch) == 1 && ch != '$') {
        if (ch == '\n' || ch == '\r' || ch == ' ' || ch == '\t')
            continue;
        p = (struct node *)malloc(sizeof(struct node));
        if (p == NULL)
            return 1;
        p->data = ch;
        p->next = NULL;
        tail->next = p;
        tail = p;
    }

    /* 第二行：a 与 key */
    if (scanf(" %c %c", &a, &key) != 2)
        return 1;
    insert(head, a, key);

    first = 1;
    for (p = head->next; p != NULL; p = p->next) {
        if (!first)
            printf(" ");
        printf("%c", p->data);
        first = 0;
    }
    printf("\n");

    p = head;
    while (p != NULL) {
        q = p->next;
        free(p);
        p = q;
    }

    return 0;
}

#include <stdio.h>
