    struct node *next;
};

/* 头结点位置不变，其后数据结点次序完全反转：逐个摘下再头插 */
void reverse_list(struct node *head) {
    struct node *p = head->next;
    struct node *q;

    head->next = NULL;
    while (p != NULL) {
        q = p->next;
        p->next = head->next;
        head->next = p;
        p = q;
    }
}

