#include <stdio.h>

struct Date {
    int y, m, d;
};

int earlier(struct Date a, struct Date b) {
    if (a.y != b.y)
        return a.y < b.y;
    if (a.m != b.m)
        return a.m < b.m;
    return a.d < b.d;
}

int main(void) {
    struct Date best, x;
    int n, i;

    if (scanf("%d", &n) != 1 || n < 1 || n > 100)
        return 1;
    if (scanf("%d %d %d", &best.y, &best.m, &best.d) != 3)
        return 1;
    for (i = 1; i < n; i++) {
        if (scanf("%d %d %d", &x.y, &x.m, &x.d) != 3)
            return 1;
        if (earlier(x, best))
            best = x;
    }
    printf("%d-%02d-%02d\n", best.y, best.m, best.d);
    return 0;
}

