#include <stdio.h>

struct Complex {
    int re, im;
};

struct Complex add(struct Complex a, struct Complex b) {
    struct Complex r;

    r.re = a.re + b.re;
    r.im = a.im + b.im;
    return r;
}

struct Complex mul(struct Complex a, struct Complex b) {
    struct Complex r;

    r.re = a.re * b.re - a.im * b.im;
    r.im = a.re * b.im + a.im * b.re;
    return r;
}

int main(void) {
    struct Complex a, b, s, p;

    if (scanf("%d %d %d %d", &a.re, &a.im, &b.re, &b.im) != 4)
        return 1;
    s = add(a, b);
    p = mul(a, b);
    printf("%d %d\n", s.re, s.im);
    printf("%d %d\n", p.re, p.im);
    return 0;
}

